insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'fhsaa-pay-for-play'), 1, 'no', 'No. Competing for money and cashing in on athletic performance still put amateur status at risk, and so does any NIL agreement that does not follow Bylaw 9.10.', 'FHSAA Bylaw 9.10.2 (a), (c), (f)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-pay-for-play' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.2', 'a) Competing for money or other monetary compensations; ... c) Capitalizing on athletic fame or performance by receiving money or gifts of a monetary nature; ... f) Accepting a Name, Image, and Likeness (NIL) agreement that does not adhere to FHSAA Bylaw 9.9.', 'visual_source_check', '2026-10-03', 'Claude (automated source research)');
