insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method, review_note, quick_status, short_answer) values ((select id from rules where slug = 'fhsaa-facilities'), 1, 'not_addressed', 'Bylaw 9.10 does not mention school facilities. It does require written consent to use school equipment. Ask your school and district.', 'FHSAA Bylaw 9.10.4.3 (equipment only)', 'researched', 'PUBLIC_POLICY_NOT_LOCATED', 'visual_source_check', 'The NIL bylaw in the 2026-27 Handbook was read in full. It does not mention facilities.', 'NOT_PUBLICLY_SPECIFIED', 'Bylaw 9.10 does not mention facilities. Ask your school and district.');
