insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-disclosure', (select id from rule_topics where slug = 'disclosure-required'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, citation, effective_note, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fhsaa-disclosure'), 1, 'yes', 'Yes. Any athlete who does NIL must sign Form GA1 and submit it to the school within five business days of signing an NIL agreement. The athletic director completes the school''s section and a copy goes to FHSAA. Submitting the form does not by itself grant eligibility.', 'FHSAA Bylaw 9.10.5; Form GA1', 'Added by the FHSAA Board in September 2024.', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'YES', 'Yes. Form GA1 goes to your school within five business days of signing.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-disclosure' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-5-sbe-2024'), 'Bylaw 9.9.5', 'A student who engages in any NIL activity must sign an ''Affidavit of Compliance with the Regulations on Amateurism and Interscholastic Athletic Eligibility.'' ... The student/parent must complete, obtain all applicable signatures and submit this form to the school within five (5) business days of signing a Name, Image, and Likeness (NIL) agreement.', 'visual_source_check', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-disclosure' and v.is_current), (select id from sources where slug = 'fhsaa-form-ga1'), 'Header, Sections A and B', 'Submission of this form DOES NOT grant eligibility. ... Once Section A is signed by the student and parent, please provide this form to the member school Athletic Director to complete Section B. ... THIS STUDENT has engaged in a Name, Image, and Likeness (NIL) agreement with: ____ ... Once Section B is completed, please send a scanned copy of this form to NIL@fhsaa.org.', 'visual_source_check', '2026-10-03', 'Claude (automated source research)');
