insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-contract-length', (select id from rule_topics where slug = 'contract-length'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'fhsaa-contract-length'), 1, 'yes_with_conditions', 'A deal is limited to the athlete''s high school eligibility and cannot extend past the high school graduation date.', 'Check the end date in the contract before you sign.', 'FHSAA Bylaw 9.10.4.1', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-contract-length' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.1', 'An NIL agreement is limited to a student-athlete''s high school period of athletic eligibility and shall not extend beyond a student-athlete''s high school graduation date.', 'visual_source_check', '2026-10-03', 'Claude (automated source research)');
