insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-penalties', (select id from rule_topics where slug = 'penalties'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'fhsaa-penalties'), 1, 'yes', 'Penalties escalate. First violation: a formal warning, and the deal must be ended or changed and any compensation returned. Second: ineligible to represent any member school for one year. Third: ineligible for the rest of the athlete''s high school career. An athlete who falsifies information or receives an impermissible benefit will be deemed ineligible under Bylaw 9.1.2.2 or Policy 36.5.2.', 'FHSAA Bylaw 9.10.6.3', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-penalties' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Penalties section', 'Any violation by a student-athlete of the provisions of Bylaw 9.9 shall result in escalating sanctions. However, a student-athlete who falsifies information or who receives an impermissible benefit will be deemed ineligible in accordance with Bylaw 9.1.2.2 or Policy 36.5.2, respectively. ... the student-athlete shall receive a formal warning. If applicable, the student shall immediately terminate/modify the NIL agreement, remove any advertisement, promotional activity, or endorsement, and return any awards, gifts, or other compensation. ... the student-athlete will be ineligible to represent any member school for a period of one year from the date of discovery. ... the student-athlete will be ineligible to compete in any interscholastic athletic contest in any sport for the duration of the student-athlete''s high school career.', 'visual_source_check', '2026-10-03', 'Claude (automated source research)');
